<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {api,post} from '../api'
const emit=defineEmits(['exit'])
const tab=ref('首页'),members=ref([]),member=ref(''),items=ref([]),medicines=ref([]),error=ref(''),busy=ref(false),voice=ref('')
const memberName=computed(()=>members.value.find(m=>m.id===member.value)?.name||'请选择成员')
const groups=computed(()=>[['🌅','早上',0,11],['☀️','中午',11,17],['🌙','晚上',17,24]].map(([icon,label,start,end])=>({icon,label,items:items.value.filter(i=>Number(i.time.split(':')[0])>=start && Number(i.time.split(':')[0])<end)})))
async function load(){window.speechSynthesis?.cancel();error.value='';items.value=[];medicines.value=[];if(!member.value)return;try{const [today,drugs]=await Promise.all([api('/today'),api('/medicines?owner='+encodeURIComponent(memberName.value))]);items.value=today.items.filter(i=>i.member_name===memberName.value);medicines.value=drugs}catch(e){error.value=e.message}}
async function confirmDose(item){busy.value=true;try{if(item.record_id){if(!confirm(`撤销${memberName.value}的“${item.medicine_name}”服药确认？`))return;await api('/records/'+item.record_id,{method:'DELETE'})}else await post('/records',{reminder_id:item.reminder_id,medicine_name:item.medicine_name,member_name:item.member_name,dose:item.dose});await load()}catch(e){error.value=e.message}finally{busy.value=false}}
function stopVoice(){window.speechSynthesis?.cancel()}
function speak(medicine){error.value='';if(!medicine?.confirmed){error.value='该药品信息尚未核对，暂不能播报，请家人核对后再试。';return}if(!('speechSynthesis' in window)){error.value='当前浏览器不支持语音，请查看文字。';return}speechSynthesis.cancel();voice.value=`${memberName.value}，${medicine.name}。每次${medicine.dose}，${medicine.frequency}。${medicine.method||''}。${medicine.risks.join('。')}`;const utterance=new SpeechSynthesisUtterance(voice.value);utterance.lang='zh-CN';utterance.rate=.8;utterance.onerror=()=>error.value='语音暂不可用，请查看下方文字。';speechSynthesis.speak(utterance)}
onMounted(async()=>{try{members.value=await api('/members');const saved=Number(localStorage.getItem('elder_member'));member.value=members.value.find(m=>m.id===saved)?.id||members.value.find(m=>m.role.includes('老人'))?.id||members.value[0]?.id||'';await load()}catch(e){error.value=e.message}})
function change(){localStorage.setItem('elder_member',String(member.value));load()}
onBeforeUnmount(()=>window.speechSynthesis?.cancel())
</script>
<template><div class="elder-content"><label>当前成员<select v-model="member" @change="change"><option v-for="m in members" :key="m.id" :value="m.id">{{m.name}}</option></select></label><p class="error" role="alert" v-if="error">{{error}}</p><template v-if="tab==='首页'"><section class="hero"><h2>{{memberName}}，记得按时吃药</h2><p>今日 {{items.length}} 项，已确认 {{items.filter(i=>i.record_id).length}} 项</p></section><p class="empty" v-if="!items.length">今天暂无服药提醒，请家人帮助设置。</p><template v-for="g in groups" :key="g.label"><div v-if="g.items.length" class="group-label">{{g.icon}}　{{g.label}}</div><article class="med-card" v-for="i in g.items" :key="i.reminder_id"><div class="med-name">{{i.medicine_name}}</div><p>{{i.time}} · {{i.dose}} · {{i.meal_label}}</p><div class="med-actions"><button class="btn-done" :disabled="busy" @click="confirmDose(i)">{{i.record_id?'✓ 已吃药 · 撤销':'我已吃药 💊'}}</button><button class="btn-voice" @click="speak(medicines.find(m=>m.id===i.medicine_id))">🔊 听一遍</button></div></article></template></template><template v-else-if="tab==='我的药'"><p class="empty" v-if="!medicines.length">当前成员药箱暂无药品。</p><article class="med-card" v-for="m in medicines" :key="m.id"><div class="med-name">{{m.name}}</div><p>{{m.dose}} · {{m.frequency}}</p><span class="tag" :class="m.confirmed?'green':'orange'">{{m.confirmed?'已核对':'待核对，不可播报'}}</span><p>用法：{{m.method||'请查看原说明书'}}</p><p v-if="m.risks.length">{{m.risks.join('；')}}</p><button @click="speak(m)">🔊 听药品说明</button></article></template><section class="panel" v-else><h2>请家人帮忙</h2><p>需要帮助时，请联系身边家人。本地版未配置联系电话，不会模拟拨打或发送消息。</p><button @click="emit('exit')">返回普通模式，查看家庭成员</button></section><section class="panel" v-if="voice"><h2>正在播报的文字</h2><p>{{voice}}</p><button @click="stopVoice">停止播报</button></section><div class="elder-nav"><button v-for="name in ['首页','我的药','联系家人']" :key="name" :class="{active:tab===name}" @click="tab=name;voice='';load()">{{name}}</button></div></div></template>
